import { LFS } from "./LFS";
import { FileSystem, PackageManager } from "./ts-pkg-manager";

async function main() {
  document.querySelector("#timing")!.textContent =
    "Downloading dependencies...";
  const fileSystem = new LFS();
  const pm = new PackageManager(fileSystem);
  const proj = await pm.resolveProject("/");
  await proj.restore();
  document.querySelector("#timing")!.textContent =
    "Dependency download complete";
}

// @ts-ignore
window.orogene = main;
